<?php
 namespace Dicom; class Dcm extends Item { protected $filename; function __construct ($filename = null) { if (isset($filename)) { $this->read($filename); } } public function read ($filename = null) { if (isset($filename)) { $this->filename = $filename; } if (isset($this->filename) && file_exists($this->filename)) { $dump = executeCmd(BIN_DCMDUMP . " -M +L \"{$this->filename}\""); $this->setElements($dump); } } public function write ($filename = null) { if (isset($filename)) { $this->filename = $filename; } $tmp = tempnam(sys_get_temp_dir(), 'dumpdcm'); $handle = fopen($tmp, 'w'); fwrite($handle, $this->dump()); fclose($handle); $res = executeCmd(BIN_DUMP2DCM . " \"{$tmp}\" \"{$this->filename}\""); unlink($tmp); return $res; } } #[\AllowDynamicProperties] class Element { function __construct ($value = null, $vr = null) { $this->set($value, $vr); } public function clear () { unset($this->Value); } public function count () { return isset($this->Value) ? count($this->Value) : 0; } public function set ($value = null, $vr = null) { if ($vr !== null && $vr !== '') { $this->vr = $vr; } unset($this->Value); if ($value !== null && $value !== '' && $value !== []) { switch ($this->vr()) { case 'PN': $obj = self::personNameToObject($value); if ($obj) { $this->Value = [$obj]; } else { $this->errorType($value); } break; case 'SQ': if (is_object($value) && ($value instanceof Item)) { $this->Value = [$value]; } else if (is_array($value) && ($value[0] instanceof Item)) { $this->Value = $value; } else { $this->errorType($value); } break; default: if (is_string($value)) { $this->Value = safe_explode('\\', $value); } else if (is_array($value)) { if (array_key_exists(0, $value)) { $this->Value = $value; } else { $this->Value = [(object)$value]; } } else { $this->Value = [$value]; } } } return $this; } public function value ($index = null) { if (isset($this->Value)) { if ($this->vr() === 'SQ') { return $index === null ? $this->Value : (isset($this->Value[$index]) ? $this->Value[$index] : null); } $v = $this->Value[0]; $arr = is_scalar($v); if ($index === null) { return $arr ? $this->Value : $v; } else { if ($arr && is_int($index)) { return isset($this->Value[$index]) ? $this->Value[$index] : null; } else { return isset($v->{$index}) ? $v->{$index} : null; } } } return null; } public function scalarValue () { if (isset($this->Value)) { switch($this->vr()) { case 'PN': return self::personNameFromObject($this->value()); case 'SQ': return null; default: $v = $this->value(); if (is_scalar($v)) { return $v; } if (is_array($v) && is_scalar($v[0])) { return implode('\\', $v); } return json_encode($v, JSON_UNESCAPED_UNICODE); } } return null; } public function dumpValue () { $v = $this->scalarValue(); if (is_string($v) && substr($v, 0, 1) === '=') { return $v; } return '[' . $v . ']'; } public function vr () { return isset($this->vr) ? $this->vr : null; } public function add ($item = null) { $item = $item ?: new Item; if (isset($this->Value)) { $this->Value[] = $item; } else { $this->Value = [$item]; } return $item; } public static function personNameToObject ($v) { $obj = null; $v = is_string($v) ? safe_explode('=', $v) : (is_object($v) ? (array)$v : $v); if (is_array($v)) { $obj = new \stdClass; if (($tmp = isset($v[0]) ? $v[0] : (isset($v['Alphabetic']) ? $v['Alphabetic'] : null))) { $obj->Alphabetic = $tmp; } if (($tmp = isset($v[1]) ? $v[1] : (isset($v['Ideographic']) ? $v['Ideographic'] : null))) { $obj->Ideographic = $tmp; } if (($tmp = isset($v[2]) ? $v[2] : (isset($v['Phonetic']) ? $v['Phonetic'] : null))) { $obj->Phonetic = $tmp; } } return $obj; } public static function personNameFromObject ($obj) { $pn = (isset($obj->Alphabetic) ? $obj->Alphabetic : '') . '=' . (isset($obj->Ideographic) ? $obj->Ideographic : '') . '=' . (isset($obj->Phonetic) ? $obj->Phonetic : ''); return rtrim($pn, '='); } protected function errorType ($value) { throw new \Exception("Неверное значение для VR = '{$this->vr()}': " . print_r($value, true)); } } #[\AllowDynamicProperties] class Item { function __construct ($source = null) { if (isset($source)) { $this->setElements($source); } } public function clear () { foreach($this as $key => $element) { unset($this->{$key}); } } public function count () { $count = 0; foreach($this as $element) { if ($element instanceof Element) { ++$count; } } return $count; } public function delete ($attr) { unset($this->{self::parseAttributes($attr)}); } public function get ($attr, $createDummy = true) { return $this->_get(self::parseAttributes($attr)) ?: ($createDummy ? new Element : null); } public function set ($attr, $value = null, $vr = null) { return $this->_set(self::parseAttributes($attr), $value, $vr); } public function setElements ($source, $ifNotExist = false) { if (is_string($source)) { $this->setElementsFromString($source, $ifNotExist); } else if (is_array($source)) { $this->setElementsFromArray($source, $ifNotExist); } else if (is_object($source) && ($source instanceof Item)) { $this->setElementsFromDicomItem($source, $ifNotExist); } else { throw new \Exception('Неверный тип данных для структуры DCM'); } } public function dump () { $res = ''; $handler = null; $handler = function ($item, $pad) use (&$handler, &$res) { foreach ($item as $attr => $v) { if ($v instanceof Element) { $attr = self::prettyAttributes($attr); $vr = $v->vr(); if ($vr === 'SQ') { $res .= "$pad$attr $vr\n"; for($i = 0, $count = $v->count(); $i < $count; ++$i) { $attr = self::prettyAttributes('FFFEE000'); $res .= "$pad  $attr na\n"; $handler($v->value($i), $pad . '    '); $attr = self::prettyAttributes('FFFEE00D'); $res .= "$pad  $attr na\n"; } $attr = self::prettyAttributes('FFFEE0DD'); $res .= "$pad$attr na\n"; } else { $res .= "$pad$attr $vr {$v->dumpValue()}\n"; } } } }; $handler($this, ''); return $res; } public function commandKeys () { $res = ''; foreach ($this as $attr => $v) { if ($v instanceof Element) { $attr = strtolower($attr); $a = substr($attr, 0, 4) . ',' . substr($attr, 4, 4); $res .= " -k \"{$a}={$v->scalarValue()}\""; } } return $res; } public static function parseAttributes ($attr) { $attr = strtoupper($attr); if (empty(KEYWORDS[$attr])) { return preg_replace('/[^\dA-F]+/', '', $attr); } return KEYWORDS[$attr]; } public static function prettyAttributes ($attr) { $attr = strtolower($attr); return '(' . substr($attr, 0, 4) . ',' . substr($attr, 4, 4) . ')'; } public static function findVr ($attr, $vr) { return empty(DICTIONARY[$attr]) ? ($vr ?: null) : DICTIONARY[$attr][0]; } public static function findAttributes ($keyword) { $keyword = strtoupper($keyword); return empty(KEYWORDS[$keyword]) ? false : KEYWORDS[$keyword]; } protected function _get ($attr) { return isset($this->{$attr}) ? $this->{$attr} : null; } protected function _set ($attr, $value, $vr) { $vr = self::findVr($attr, $vr); if (isset($this->{$attr})) { return $this->{$attr}->set($value, $vr); } else { return ($this->{$attr} = new Element($value, $vr)); } } protected function setElementsFromString ($source, $ifNotExist) { $source = preg_replace('/#./', '', $source); $count = preg_match_all('/' .'^(?:\s*|I:\s*)' .'\(((?:[^\w]*[\da-f]){8})[^\w]*\)' .'(?:\s+(\D{2}))?' .'\s+(?|(=\S+)|\[(.*?)\]|\((?:.*?)\)|<(?:.*?)>|(\S+))' .'/im', $source, $matches); if ($count) { $sq = null; $item = $this; $sqStack = []; $itemStack = []; for ($i = 0; $i < $count; ++$i) { $attr = self::parseAttributes($matches[1][$i]); if (!($ifNotExist && isset($item->{$attr}))) { $vr = self::findVr($attr, $matches[2][$i]); $value = $matches[3][$i]; if ($vr === 'SQ') { array_push($sqStack, $sq); $sq = $item->_set($attr, $value, $vr); } else if ($attr === 'FFFEE0DD') { $sq = array_pop($sqStack); } else if ($attr === 'FFFEE000') { array_push($itemStack, $item); $item = $sq->add(); } else if ($attr === 'FFFEE00D') { $item = array_pop($itemStack); } else { $item->_set($attr, trim($value), $vr); } } } } } protected function setElementsFromArray ($source, $ifNotExist) { $handler = null; $handler = function ($item, &$arr) use (&$handler, $ifNotExist) { foreach ($arr as $k => &$v) { $attr = self::parseAttributes($k); if (!($ifNotExist && isset($item->{$attr}))) { $vr = self::findVr($attr, isset($v['vr']) ? $v['vr'] : null); $value = isset($v['value']) ? $v['value'] : (isset($v['Value']) ? $v['Value'] : $v); if ($vr === 'SQ') { $sq = $item->_set($attr, null, $vr); if (!empty($value) && is_array($value)) { foreach ($value as $kItem => &$vItem) { $handler($sq->add(), $vItem); } } } else { $item->_set($attr, $value, $vr); } } } }; $handler($this, $source); } protected function setElementsFromDicomItem ($source, $ifNotExist) { $handler = null; $handler = function ($item, $obj) use (&$handler, $ifNotExist) { foreach ($obj as $attr => $v) { if ($v instanceof Element && !($ifNotExist && isset($item->{$attr}))) { $vr = $v->vr(); if ($vr === 'SQ') { $sq = $item->_set($attr, null, $vr); for($i = 0, $count = $v->count(); $i < $count; ++$i) { $handler($sq->add(), $v->value($i)); } } else { $item->_set($attr, $v->value(), $vr); } } } }; $handler($this, $source); } } 